CREATE TABLE Customers (
    customer_id INT PRIMARY KEY,
    customer_name VARCHAR(100)
);

CREATE TABLE Orders (
    order_id INT PRIMARY KEY,
    customer_id INT,
    order_date DATE,
    FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

INSERT INTO Customers (customer_id, customer_name) VALUES (1, 'Alice');
INSERT INTO Customers (customer_id, customer_name) VALUES (2, 'Bob');

-- Successful insert: customer_id 1 exists
INSERT INTO Orders (order_id, customer_id, order_date) VALUES (101, 1, '2023-01-01');

-- Failed insert: customer_id 999 does not exist
INSERT INTO Orders (order_id, customer_id, order_date) VALUES (102, 999, '2023-01-02');
